def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    # Identify alive opponents
    alive = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive.append((oid, o))

    # If no opponents, bid conservatively
    if not alive:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    # Read yesterday bids from previous_trace (immediate reaction)
    yesterday_bids = []
    for oid, o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = (sum(yesterday_bids) / len(yesterday_bids)) if yesterday_bids else 0.0

    # Determine scarcity pressure from supply (higher supply -> can bid less)
    # Normalize between MIN_SUPPLY and MAX_SUPPLY
    if MAX_SUPPLY > MIN_SUPPLY:
        scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        scarcity = 0.5
    scarcity = max(0.0, min(1.0, float(scarcity)))

    # Base bid band: target around avg_prev with a small premium depending on scarcity and our HP.
    # If they were bidding extremely high yesterday, slightly undercut to win on a marginal edge.
    if highest_prev >= 100.0:
        target = avg_prev * (0.96 + 0.04 * scarcity)
        # If we're in danger, don't underbid too much
        if my_hp <= 2.5 or my_no_water_days >= 2:
            target = max(target, highest_prev * 0.80)
    else:
        target = avg_prev * (0.98 + 0.06 * scarcity)
        # If we have decent HP, avoid overpaying
        if my_hp >= 7.0 and my_no_water_days == 0:
            target = min(target, avg_prev * 0.92)

    # Convert target to a practical cap tied to our budget and salary
    # Keep within reasonable fraction of DAILY_SALARY to avoid bankruptcy.
    danger = (my_hp <= 2.5) or (my_no_water_days >= 2)
    if danger:
        max_affordable = DAILY_SALARY * 0.95
    else:
        max_affordable = DAILY_SALARY * 0.65

    bid = float(min(my_budget, max_affordable, max(1.0, target)))

    # Ensure integer-like stability (bids are typically continuous, but we keep it precise)
    return bid

